                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and out[yy][xx] == color:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            comps.append((len(comp), color, comp))

    # Recolor the largest connected patterned object.
